import json,sys,collections
def load(p):
    d={}
    for l in open(p):
        try: o=json.loads(l)
        except: continue
        k=(tuple(o['t']),o['w'],tuple(o['m'] or []))
        d[k]=o['r']
    return d
base=load('runs/base.jsonl')
for v in sys.argv[1:]:
    other=load(f'runs/{v}.jsonl')
    tables=collections.Counter(); diff=collections.Counter(); ex={}
    for k,r in base.items():
        tid=k[0]
        tables[tid]+=1
        if k in other and other[k]!=r:
            diff[tid]+=1
            ex.setdefault(tid,[]).append((k[1],k[2],r,other[k]))
    print(f"=== variant {v}: {len(base)} distinct inputs, {sum(diff.values())} differ")
    for tid,n in sorted(tables.items(), key=lambda x:-x[1]):
        name=",".join(t or "·" for t in tid)
        print(f"  {diff[tid]:5d}/{n:5d}  {name[:110]}")
    if '-v' in sys.argv[0:1]: pass
EOF
