	"fmt"
	"testing"
)

func y(c Column[string]) Column[string] { c.Optional, c.Yields = true, true; return c }

func TestZZProtoNumbers(t *testing.T) {
	cases := []struct {
		name string
		cols []Column[string]
		w    int
		m    []int
	}{
		{"T1 yields", []Column[string]{content(10, 1), y(fixed(8)), fixed(5)}, 47, []int{30}},
		{"T2 noflag", []Column[string]{content(10, 1), optional(fixed(8)), fixed(5)}, 47, []int{30}},
		{"T3a optcontent suffices", []Column[string]{content(10, 0), optional(content(12, 1)), y(fixed(8)), fixed(5)}, 2 + 8 + 20 + 20 + 8 + 5 - 6, []int{20, 20}},
		{"T3b optcontent short", []Column[string]{content(10, 0), optional(content(12, 1)), y(fixed(8)), fixed(5)}, 2 + 8 + 20 + 20 + 8 + 5 - 12, []int{20, 20}},
		{"T4 stops at non-yield", []Column[string]{content(10, 1), optional(fixed(6)), y(fixed(8)), fixed(5)}, 2 + 8 + 30 + 6 + 8 + 5 - 4, []int{30}},
		{"T4b after yield gone", []Column[string]{content(10, 1), optional(fixed(6)), y(fixed(8)), fixed(5)}, 2 + 8 + 30 + 6 + 8 + 5 - 12, []int{30}},
		{"T5 not next in queue", []Column[string]{content(10, 1), y(fixed(8)), optional(fixed(6)), fixed(5)}, 2 + 8 + 30 + 6 + 8 + 5 - 4, []int{30}},
		{"T6 yields w/o optional", []Column[string]{content(10, 1), func() Column[string] { c := fixed(8); c.Yields = true; return c }(), fixed(5)}, 47, []int{30}},
	}
	for _, c := range cases {
		fmt.Printf("%-26s w=%d -> %v\n", c.name, c.w, solveWidths(c.cols, c.w, c.m))
	}
}
EOF
for v in "" G; do echo "== variant '$v'"; DT_VARIANT=$v go test -count=1 -v -run TestZZProtoNumbers ./internal/ui/datatable/ | grep -- "->"; done

